      "cell_id": "proband_zygosity",
      "note": "The report does not use the word heterozygous, but 112 of 234 alternate reads supports that call."
    },
    {
      "cell_id": "mother_reads",
      "note": "Parental read counts are referred to a Confirmation section that is not in the excerpt, so this cell was not changed."
    },
    {
      "cell_id": "father_reads",
      "note": "Parental read counts are referred to a Confirmation section that is not in the excerpt, so this cell was not changed."
    },
