    },
    {
      "cell_id": "v1_acmg_criteria",
      "note": "The excerpt states a Pathogenic classification but does not list PVS1, PM2_Supporting, or PP4."
    },
    {
      "cell_id": "v1_gnomad",
      "note": "An overall gnomAD v4.1 allele frequency of 0 is not stated in the excerpt."
    },
    {
      "cell_id": "secondary_findings",
      "note": "ACMG secondary findings are not mentioned in the excerpt."
    },
    {
      "cell_id": "inheritance",
      "note": "De novo inheritance is not explicitly stated in the excerpt and depends on the Confirmation section."
    }
  ]
}

{
  "changes": [
    {
      "cell_id": "v1_zygosity",
      "old": "heterozygous",
      "new": "homozygous",
      "reason": "Sanger sequencing confirmed the IDUA variant as homozygous in the proband, with 96 of 97 reads supporting the alternate allele."
    },
    {
      "cell_id": "v1_vaf",
      "old": "1.40",
      "new": "0.99",
      "reason": "The report does not give a variant allele fraction of 1.40; 96 of 97 alternate reads is a fraction of approximately 0.99."
    },
    {
      "cell_id": "v1_gnomad_overall",
      "old": "0.00012",
      "new": "not reported",
      "reason": "A gnomAD v4.1 overall allele frequency is given only for the GALNS variant, not for the IDUA variant."
    },
    {
      "cell_id": "v1_af_regional",
      "old": "0.00053",
      "new": "not reported",
      "reason": "The report does not describe a regional carrier survey or any allele frequency in the community of origin."
    },
    {
      "cell_id": "v1_acmg_criteria",
      "old": "PS3, PM2_Supporting, PM3, PP1, PP4",
      "new": "not reported",
      "reason": "The IDUA variant is classified as Pathogenic, but the report does not list the ACMG/AMP criteria codes applied to it."
    },
    {
      "cell_id": "secondary_findings",
      "old": "none",
      "new": "not reported",
      "reason": "The report does not mention ACMG secondary findings (SF v3.2) or state that none were identified."
    },
    {
      "cell_id": "diagnosis",
      "old": "MPS I, attenuated (Hurler-Scheie)",
      "new": "mucopolysaccharidosis type I",
      "reason": "The report associates the finding with mucopolysaccharidosis type I and lists OMIM #607014, #607015 and #607016 without specifying an attenuated or Hurler-Scheie subtype."
    }
  ],
  "notes": [
    {
      "cell_id": "v1_reads",
      "note": "96/97 matches the report; the single reference read had base quality below 20, so this count is compatible with the homozygous Sanger result and was not changed."
    },
    {
      "cell_id": "v1_inheritance",
      "note": "Autosomal recessive is stated for the associated condition and both parents are heterozygous, so biparental inheritance is supported even though that word is not used verbatim."
    },
    {
      "cell_id": "v2_gnomad_overall",
      "note": "The frequency 0.00004 is the gnomAD v4.1 overall allele frequency stated for the GALNS variant and was left unchanged."
    }
  ]
}

