  "notes": [
    {
      "cell_id": "v1_reads",
      "note": "96/97 is the count given in the report; the single reference read had base quality below 20, and Sanger confirmed homozygosity, so the read count should not be altered to 97/97."
    },
    {
      "cell_id": "v1_inheritance",
      "note": "Autosomal recessive is stated for MPS I, and biparental inheritance is supported by heterozygous Sanger confirmation in both parents."
    },
    {
      "cell_id": "cnv",
      "note": "Kept as none because the report explicitly states that no clinically relevant copy-number variant was identified in the trio."
    }
  ]
}
